update public.offsite_config set conteudo=jsonb_set(jsonb_set(jsonb_set(jsonb_set(jsonb_set(conteudo,'{bscTexto}','"2. Estrutura Causa-Efeito do Balanced Scorecard (BSC)\n\nO Off-site abordará as quatro perspectivas fundamentais do BSC em ordem ascendente de causa e efeito. Cada bloco encadeia a lógica de geração de valor: capacitação interna de pessoas gera processos eficientes, que entregam uma proposta de valor superior aos clientes, resultando em crescimento com geração de caixa e expansão do valor da base, a serviço da North Star (alunos ativos e adimplentes na PPG) e do BHAG de 1 milhão de vidas salvas até 2034."'::jsonb),'{perguntas,0,14}','{"id": "0.13", "kpis": ["P01.01", "P01.03", "F01.03", "C02-a.02"], "tipo": "multipla", "ajuda": "Hoje 55% da base está na faixa Perdidos.", "apoio": {"como": "aponte por que o aluno não sobe na escada.", "porque": "recompra e ascensão custam muito menos que captação; na Rev.03, a receita de expansão da base (ascensão e recompra) é o KPI estratégico da F.02.", "entregar": "os três principais motivos e a ação."}, "texto": "", "extras": [{"nome": "Ação que você propõe", "tipo": "curto"}, {"nome": "Dos alunos “perdidos” na matriz RFV, quanto é nosso pré-ICP, ICP ou não é nosso ICP? Traga os dados.", "tipo": "texto", "cadeiras": ["Iuri Franco", "Guilherme Vieira"], "opcional": true}, {"nome": "O churn está baixo porque o aluno está satisfeito ou porque o contrato o prende?", "tipo": "escolha", "opcoes": ["Satisfação", "Contrato", "Ambos"], "cadeiras": ["Guilherme Vieira", "Yuri Ribeiro"], "opcional": true}, {"nome": "O que sinaliza essa diferença?", "tipo": "texto", "cadeiras": ["Guilherme Vieira", "Yuri Ribeiro"], "opcional": true}, {"nome": "Qual comportamento do aluno satisfeito mais gera receita para a LM?", "tipo": "escolha", "opcoes": ["Renovar", "Comprar outro produto", "Indicar"], "cadeiras": ["Guilherme Vieira", "Iuri Franco"], "opcional": true}, {"nome": "Você tem o dado, ou é percepção?", "tipo": "escolha", "opcoes": ["Tenho o dado", "É percepção"], "cadeiras": ["Guilherme Vieira", "Iuri Franco"], "opcional": true}, {"nome": "A indicação saltou de 4% para 34% em três meses. O que causou, e é replicável ou foi pontual?", "tipo": "texto", "opcional": true}, {"nome": "Qual produto da escada de valor dos nossos produtos core (FPG, ACLS, PPG) o aluno já pede e ainda não temos?", "tipo": "texto", "opcional": true}], "limite": 3, "opcoes": ["Não viu valor cedo (TTFV)", "Agenda ou acesso à prática", "Preço ou condição", "Falta de oferta no momento certo", "Atendimento", "Mudança de foco de carreira", "Outro"], "titulo": "Retenção e escada de produtos", "cadeiras": ["Guilherme Vieira", "Iuri Franco", "Felipe Souza", "Yuri Ribeiro"], "objetivos": ["F.02 Expandir valor da base com margem"]}'::jsonb),'{perguntas,0,15}','{"id": "0.14", "kpis": ["F02", "F02.04", "F02.05"], "nota": "Fatos trazidos pelo financeiro no card antes do envio: participação do boleto nas vendas e gastos fora do orçamento da sua área em 2026, além dos KPIs acima.", "tipo": "matriz", "apoio": {"como": "os números já vêm do financeiro; aponte onde sua área influencia e o que você priorizaria.", "porque": "na Rev.03, o caixa passa a ser o KPI estratégico do financeiro: geração de caixa operacional sem parcelamento fiscal, com o CAC, e acima do piso. No caso base, o caixa fica abaixo do piso em 2027, e o erro do forecast de caixa hoje é de 92%.", "entregar": "onde sua área influencia o caixa e o que muda na alavanca de maior impacto."}, "grupo": "Financeira", "itens": ["Prazo de recebimento das vendas", "Forma de pagamento das vendas (cartão ou à vista × boleto)", "Prazo de pagamento a fornecedores", "Previsão das despesas da área (erro do forecast)", "Gastos fora do orçamento", "Outro"], "texto": "", "campos": [{"nome": "Minha área influencia", "tipo": "escolha", "opcoes": ["Diretamente", "Indiretamente", "Não influencia"]}], "extras": [{"nome": "Entre as alavancas que sua área influencia, qual tem maior impacto no caixa de 2027? (1ª)", "tipo": "escolha", "opcional": true, "opcoesDaMatriz": true}, {"nome": "E a segunda de maior impacto? (2ª)", "tipo": "escolha", "opcional": true, "opcoesDaMatriz": true}, {"nome": "O que sua área se compromete a mudar na alavanca de maior impacto?", "tipo": "texto", "opcional": true}, {"nome": "Por que as despesas da sua área desviaram do previsto em 2026?", "tipo": "texto", "opcional": true}], "titulo": "Conversão da operação em caixa", "objetivos": ["F.01 Crescer gerando caixa"]}'::jsonb),'{perguntas,0,16}','{"id": "0.15", "kpis": ["F01.02", "F01.01"], "tipo": "matriz", "apoio": {"como": "avalie o peso de cada prática na sua área.", "porque": "venda de alto risco infla a receita e consome capital de giro. Na Rev.03, a inadimplência por safra com a recuperação (PCLD) e a fatia da receita da PPG no cartão ou à vista passam a ser indicadores do caixa; o número crítico de 2027 é levar o boleto a cerca de 20% das vendas.", "entregar": "o que restringir e o que incentivar."}, "itens": ["Boleto parcelado longo", "Descontos fora da política", "Venda fora do ICP", "Renegociação de contratos", "Cobrança tardia", "Outro"], "texto": "", "campos": [{"nome": "Avaliação", "tipo": "escolha", "opcoes": ["Peso alto", "Médio", "Baixo", "Não se aplica"]}], "extras": [{"nome": "Na sua visão, qual a estratégia para chegarmos a cerca de 2.000 alunos ativos e adimplentes na PPG em 2027, a North Star da LM?", "tipo": "texto", "opcional": true}], "titulo": "Qualidade das vendas e inadimplência", "cadeiras": ["Felipe Souza", "Guilherme Vieira", "Bruno Garcia"], "objetivos": ["F.01 Crescer gerando caixa"]}'::jsonb),'{perguntas,7,0}','{"id": "7.2", "tipo": "grupo", "texto": "Se você tivesse que operar 2027 com menos custo de estrutura:", "campos": [{"nome": "O que mudaria primeiro com 15% menos custo de estrutura"}, {"nome": "Qual custo da sua área cresce junto com a receita e não deveria crescer, porque reduz a margem de contribuição?", "opcional": true}]}'::jsonb) where id='2027' and conteudo#>>'{perguntas,0,14,id}'='0.13' and conteudo#>>'{perguntas,0,15,id}'='0.14' and conteudo#>>'{perguntas,0,16,id}'='0.15' and conteudo#>>'{perguntas,7,0,id}'='7.2';